        const axis = (o1, o2, n1, n2) => o1 && o2 ? -1 : o1 ? 0 : o2 ? 4 : n1 ? 1 : n2 ? 3 : 2;
        const cx = axis(open(tx - 1, ty), open(tx + 1, ty), open(tx - 2, ty), open(tx + 2, ty));
        const cy = axis(open(tx, ty - 1), open(tx, ty + 1), open(tx, ty - 2), open(tx, ty + 2));
