        c.rect(x, y + 7, T, 1, hex('#100c1c')); c.rect(x + (ty % 2 ? 4 : 11), y + 1, 1, 6, hex('#100c1c'));
        if (h % 7 === 0) c.rect(x + 3 + (h % 9), y + 10, 2, 2, hex('#3fb8d8'));   // a lit window
