// Jungle: 384x216 pixel art at 1x
const plx = n => web(`bg/jungle/plx-${n}.png`);
parallax('jungle_far', [plx(2)], 384, SHADE.jungle); parallax('jungle_mid', [plx(3)], 384, SHADE.jungle); parallax('jungle_near', [plx(4), plx(5)], 384, SHADE.jungle);
