// Hell: the painted cave layers become flat silhouettes (the GBA can't hold the painting), 0.4x so a layer is 512 wide
function silhouette(file, scale) {
  const src = web(file), w = Math.round(src.w * scale), h = Math.round(src.h * scale), c = new Canvas(w, h);
  let r = 0, g = 0, b = 0, n = 0;
  for (let i = 0; i < src.d.length; i += 4) if (src.d[i + 3] >= 128) { r += src.d[i]; g += src.d[i + 1]; b += src.d[i + 2]; n++; }
  const col = [r / n, g / n, b / n];
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) if (src.get(Math.floor(x / scale), Math.floor(y / scale))[3] >= 128) c.set(x, y, [...col, 255]);
  const out = new Canvas(w, 256); out.blit(c, 0, h - 256, w, 256, 0, 0);   // keep the bottom 256 rows (layers are bottom-anchored)
  return out;
}
const cave = n => silhouette(`bg/cave/${n}.png`, 0.4);
// Doom fire band along the bottom of the near layer, from the web game's stepFire() rules (run until it settles).
// The flames have to burn out inside the band, or they're cut off in a straight line along its top (the user's
// complaint). So the band is 36 rows (2x2 px cells), cooling at the web game's rate in its lower rows and ever faster
// in the upper ones: the base stays as full as before, and the tops break up into uneven licks well below the edge.
function fireBand(c) {
  const FW = 256, FH = 36, HOT = 30, heat = new Uint8Array(FW * FH);
  const PAL = [[7,7,7],[31,7,7],[47,15,7],[71,15,7],[87,23,7],[103,31,7],[119,31,7],[143,39,7],[159,47,7],[175,63,7],[191,71,7],[199,71,7],[223,79,7],[223,87,7],[223,87,7],[215,95,7],[215,95,7],[215,103,15],[207,111,15],[207,119,15],[207,127,15],[207,135,23],[199,135,23],[199,143,23],[199,151,31],[191,159,31],[191,159,31],[191,167,39],[191,167,39],[191,175,47],[183,175,47]];
  const noise = x => Math.sin(x * 0.11) * 0.5 + Math.sin(x * 0.047 + 1.3) * 0.35 + Math.sin(x * 0.23 + 4.1) * 0.15;
  let seed = 7; const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
  for (let step = 0; step < 200; step++) {
    for (let x = 0; x < FW; x++) heat[(FH - 1) * FW + x] = Math.round(HOT * Math.max(0.35, Math.min(1, 0.68 + 0.55 * noise(x))));
    for (let y = 1; y < FH; y++) for (let x = 0; x < FW; x++) {
      const v = heat[y * FW + x], r = Math.round(rnd() * 3) & 3, nx = (x - r + 1 + FW) % FW;   // wraps, so the band tiles
      const extra = Math.max(0, (24 - y) / 24) * 0.9;   // extra cooling: none in the bottom 12 rows, rising to 0.9 at the top
      heat[(y - 1) * FW + nx] = v > 0 ? Math.max(0, v - (r & 1) - (rnd() < extra ? 1 : 0)) : 0;
    }
  }
  for (let y = 0; y < FH; y++) for (let x = 0; x < FW; x++) {
    const v = heat[y * FW + x]; if (v < 5) continue;   // the faintest heat would fade into the cave
    const col = PAL[Math.min(PAL.length - 1, v)];
    for (const [dx, dy] of [[0, 0], [1, 0], [0, 1], [1, 1]]) for (let rep = 0; rep < c.w; rep += 512) c.set(rep + x * 2 + dx, 256 - FH * 2 + y * 2 + dy, [...col, 255]);
  }
}
