while (st.length) { const [x, y] = st.pop(); const k = x + ',' + y; if (x < panel.x0 || y < panel.y0 || x > panel.x1 || y > panel.y1 || bgMask.has(k) || !isWhite(x, y)) continue; bgMask.add(k); st.push([x + 1, y], [x - 1, y], [x, y + 1], [x, y - 1]); }
