// ---------- Startup screens: 256-colour (8bpp) full-screen pictures ----------
// Writes a 256x256 canvas as an 8bpp background (palette index 0 = transparent, showing the black backdrop)
function emitBg8(name, c, pal) {
  const px = indexed(c, pal), full = [TRANSPARENT, ...pal]; while (full.length < 256) full.push([0, 0, 0]);
  const rowBytes = 256, size = 14 + 40 + 1024 + rowBytes * 256, b = Buffer.alloc(size);
  b.write('BM', 0); b.writeUInt32LE(size, 2); b.writeUInt32LE(14 + 40 + 1024, 10);
  b.writeUInt32LE(40, 14); b.writeInt32LE(256, 18); b.writeInt32LE(256, 22); b.writeUInt16LE(1, 26); b.writeUInt16LE(8, 28);
  b.writeUInt32LE(0, 30); b.writeUInt32LE(rowBytes * 256, 34); b.writeUInt32LE(256, 46); b.writeUInt32LE(256, 50);
  full.forEach((col, i) => { b[54 + i * 4] = col[2]; b[55 + i * 4] = col[1]; b[56 + i * 4] = col[0]; });
  for (let y = 0; y < 256; y++) for (let x = 0; x < 256; x++) b[1078 + (255 - y) * rowBytes + x] = px[y * 256 + x];
  fs.writeFileSync(path.join(OUT_G, name + '.bmp'), b);
  fs.writeFileSync(path.join(OUT_G, name + '.json'), JSON.stringify({ type: 'regular_bg', bpp_mode: 'bpp_8' }, null, 4) + '\n');
}
// A canvas's colour histogram (opaque pixels only)
function histogram(c) {
  const hist = new Map();
  for (let i = 0; i < c.d.length; i += 4) if (c.d[i + 3]) { const k = key([c.d[i], c.d[i + 1], c.d[i + 2]]); hist.set(k, (hist.get(k) || 0) + 1); }
  return hist;
}
// Median cut then a few k-means passes: for pictures with thousands of colours, where reduce() (pairwise merging) is far
// too slow
function medianCut(hist, n) {
  const all = [...hist.entries()].map(([k, w]) => ({ c: [k >> 16 & 255, k >> 8 & 255, k & 255], w }));
  let boxes = [all];
  const spread = box => { let best = 0, ch = 0; for (let k = 0; k < 3; k++) { let lo = 255, hi = 0; for (const o of box) { lo = Math.min(lo, o.c[k]); hi = Math.max(hi, o.c[k]); } if (hi - lo > best) { best = hi - lo; ch = k; } } return { best, ch }; };
  while (boxes.length < n) {
    let bi = -1, bs = 0, bch = 0;
    boxes.forEach((box, i) => { if (box.length < 2) return; const { best, ch } = spread(box), w = box.reduce((t, o) => t + o.w, 0), sc = best * Math.sqrt(w); if (sc > bs) { bs = sc; bi = i; bch = ch; } });
    if (bi < 0) break;
    const box = boxes[bi].sort((a, b) => a.c[bch] - b.c[bch]), half = box.reduce((t, o) => t + o.w, 0) / 2;
    let acc = 0, cut = 1; for (let i = 0; i < box.length - 1; i++) { acc += box[i].w; if (acc >= half) { cut = i + 1; break; } }
    boxes.splice(bi, 1, box.slice(0, cut), box.slice(cut));
  }
  let cents = boxes.map(box => { const w = box.reduce((t, o) => t + o.w, 0); return [0, 1, 2].map(k => box.reduce((t, o) => t + o.c[k] * o.w, 0) / w); });
  for (let pass = 0; pass < 4; pass++) {
    const sum = cents.map(() => [0, 0, 0, 0]);
    for (const o of all) { const i = nearest(cents, o.c), t = sum[i]; t[0] += o.c[0] * o.w; t[1] += o.c[1] * o.w; t[2] += o.c[2] * o.w; t[3] += o.w; }
    cents = cents.map((c, i) => sum[i][3] ? [sum[i][0] / sum[i][3], sum[i][1] / sum[i][3], sum[i][2] / sum[i][3]] : c);
  }
  return cents.map(c => q5(c.map(Math.round)));
}

// ---------- Dreamweaver Studios logo (the first startup screen) ----------
// The logo's artwork (219x147 inside a 355x355 black square) fits the GBA screen at its own size, so it's cropped to
// 240x160 around the artwork, not scaled. Its anti-aliased edges and purple gradient need more than 16 colours, so it's
// a 256-colour (8bpp) background, centred in a 256x256 map; black is left as the transparent backdrop.
{
  const src = loadPng(path.resolve(WEB, '../DW Studios logo (large).png'));
  let x0 = src.w, y0 = src.h, x1 = -1, y1 = -1;
  for (let y = 0; y < src.h; y++) for (let x = 0; x < src.w; x++) {
    const [r, g, b] = src.get(x, y);
    if (r + g + b > 30) { x0 = Math.min(x0, x); x1 = Math.max(x1, x); y0 = Math.min(y0, y); y1 = Math.max(y1, y); }
  }
  const cx = Math.round((x0 + x1) / 2), cy = Math.round((y0 + y1) / 2), c = new Canvas(256, 256);
  for (let y = 0; y < 160; y++) for (let x = 0; x < 240; x++) {
    const p = src.get(cx - 120 + x, cy - 80 + y);
    if (p[3] >= 128 && q5(p.slice(0, 3)).some(v => v > 0)) c.set(8 + x, 48 + y, [...q5(p.slice(0, 3)), 255]);
  }
  const pal = reduce(histogram(c), 255);
  emitBg8('dw_logo', c, pal);
  console.log(`dw_logo: artwork ${x1 - x0 + 1}x${y1 - y0 + 1}, ${pal.length} colours`);
}

// ---------- Super Mario Hellbound title picture (the second startup screen) ----------
// Since 2026-10-16 the user's new 1312x816 title art (a JPG, turned into a PNG with Windows' own image library, as
// pngjs can't read JPGs). Scaled down to fill the screen's height (256x160, area-averaged) with 8 px trimmed off each
// side, and reduced from thousands of colours to 255. (The first title art was a 2000x1249 PNG, cropped the same way.)
{
  const jpg = path.resolve(WEB, '../Super Mario Run and Gun/Super Mario Hellbound NEW Title Screen.jpg'), png = path.join(os.tmpdir(), 'smhb-title.png');
  require('child_process').execFileSync('powershell.exe', ['-NoProfile', '-Command',
    `Add-Type -AssemblyName System.Drawing; $i = [System.Drawing.Image]::FromFile('${jpg.replace(/'/g, "''")}'); $i.Save('${png}', [System.Drawing.Imaging.ImageFormat]::Png); $i.Dispose()`]);
  const src = loadPng(png);
  const small = downscale(src, 256, 160), c = new Canvas(256, 256);
  for (let y = 0; y < 160; y++) for (let x = 0; x < 240; x++) {
    const p = small.get(8 + x, y);
    if (p[3] >= 128) c.set(8 + x, 48 + y, [...q5(p.slice(0, 3)), 255]);
  }
  const hist = histogram(c), pal = medianCut(hist, 255);
  emitBg8('title_art', c, pal);
  console.log(`title_art: ${hist.size} colours -> ${pal.length}`);
  if (process.env.SMHB_PREVIEW) {   // optional check: the quantised picture as a PNG
    const out = new PNG({ width: 240, height: 160 }), px = indexed(c, pal);
    for (let y = 0; y < 160; y++) for (let x = 0; x < 240; x++) { const v = px[(48 + y) * 256 + 8 + x], col = v ? pal[v - 1] : [0, 0, 0], o = (y * 240 + x) * 4; out.data[o] = col[0]; out.data[o + 1] = col[1]; out.data[o + 2] = col[2]; out.data[o + 3] = 255; }
    fs.writeFileSync(process.env.SMHB_PREVIEW, PNG.sync.write(out));
  }
}

// ---------- Level header (all the levels) ----------
const n = v => Math.round(v);
const FOE = { alien: 0, death: 1, beast: 2, mech: 3 };   // mech: World 3-1's (gbaFoe; an alien to the web builder)
