  h += `\nnamespace ${ns}\n{\n    constexpr uint8_t grid[${ROWS * L.w}] = {\n${L.grid.map(r => '        ' + r.join(',')).join(',\n')}\n    };\n`;
  h += arr('point', 'coins', L.coins, c => `{${n(c.x)}, ${n(c.y)}}`);
  h += arr('point', 'embers', L.embers, e => `{${n(e.x)}, ${n(e.y)}}`);
