h += `\n// The biggest tile-background map (cells) of a level with a rocket launcher (main.cpp's RAM copy is sized to it)\nconstexpr int rocket_map_cells = ${Math.max(1, ...LEVELS.filter(l => l.def.rocket).map(l => bgWidths[l.def.name] / 8 * 32))};\n`;
