fs.writeFileSync(path.join(OUT_I, 'level_bgs.h'), lb);
for (const old of ['level_jungle.h', 'jungle_sky.h']) fs.rmSync(path.join(OUT_I, old), { force: true });

// ---------- Sound: MP3 or OGG -> 8-bit WAV sound effects, and looping XM music ----------
