    const dec = ogg ? new OggVorbisDecoder() : new MPEGDecoder(); await dec.ready; // a fresh decoder per file: reusing one after reset() fails
    const bytes = new Uint8Array(fs.readFileSync(path.resolve(WEB, file)));
