    const { mono, rate: srcRate, peak } = await decodeMono(path.resolve(WEB, '../Super Mario Run and Gun/SFX/flamethrower-sound-effect.mp3'));
    const rate = 22050, perFrame = rate / 59.7275, pcm = resample(mono, srcRate, rate, peak, false, FLAME_BOOST);
    const startFrames = 30, a = Math.round(startFrames * perFrame), xf = Math.round(0.1 * rate);
    const loopFrames = Math.floor((pcm.length - a - xf) / perFrame), n = Math.round(loopFrames * perFrame);
